11	// headerCarrierKey is the context key for storing headers to be set in the response.
12	type headerCarrierKey struct{}
13	
14	// HeaderCarrier stores headers that need to be set in the response.
15	//
16	// Problem: The codebase supports two protocols simultaneously:
17	//   - Native gRPC: Uses grpc.SetHeader() to set response headers
18	//   - Connect-RPC: Uses connect.Response.Header().Set() to set response headers
19	//
20	// Solution: HeaderCarrier provides a protocol-agnostic way to set headers.
21	//   - Service methods call SetResponseHeader() regardless of protocol
22	//   - For gRPC requests: SetResponseHeader uses grpc.SetHeader directly
23	//   - For Connect requests: SetResponseHeader stores headers in HeaderCarrier
24	//   - Connect wrappers extract headers from HeaderCarrier and apply to response
25	//
26	// This allows service methods to work with both protocols without knowing which one is being used.
27	type HeaderCarrier struct {
28		headers map[string]string
29	}
30	
31	// newHeaderCarrier creates a new header carrier.
32	func newHeaderCarrier() *HeaderCarrier {
33		return &HeaderCarrier{
34			headers: make(map[string]string),
35		}
36	}
37	
38	// Set adds a header to the carrier.
39	func (h *HeaderCarrier) Set(key, value string) {
40		h.headers[key] = value
41	}
42	
43	// Get retrieves a header from the carrier.
44	func (h *HeaderCarrier) Get(key string) string {
45		return h.headers[key]
46	}
47	
48	// All returns all headers.
49	func (h *HeaderCarrier) All() map[string]string {
50		return h.headers
51	}
52	
53	// WithHeaderCarrier adds a header carrier to the context.
54	func WithHeaderCarrier(ctx context.Context) context.Context {
55		return context.WithValue(ctx, headerCarrierKey{}, newHeaderCarrier())
56	}
57	
58	// GetHeaderCarrier retrieves the header carrier from the context.
59	// Returns nil if no carrier is present.
60	func GetHeaderCarrier(ctx context.Context) *HeaderCarrier {
61		if carrier, ok := ctx.Value(headerCarrierKey{}).(*HeaderCarrier); ok {
62			return carrier
63		}
64		return nil
65	}
66	
67	// SetResponseHeader sets a header in the response.
68	//
69	// This function works for both gRPC and Connect protocols:
70	//   - For gRPC: Uses grpc.SetHeader to set headers in gRPC metadata
71	//   - For Connect: Stores in HeaderCarrier for Connect wrapper to apply later
72	//
73	// The protocol is automatically detected based on whether a HeaderCarrier
74	// exists in the context (injected by Connect wrappers).
75	func SetResponseHeader(ctx context.Context, key, value string) error {
76		// Try Connect first (check if we have a header carrier)
77		if carrier := GetHeaderCarrier(ctx); carrier != nil {
78			carrier.Set(key, value)
79			return nil
80		}
81	
82		// Fall back to gRPC
83		return grpc.SetHeader(ctx, metadata.New(map[string]string{
84			key: value,
85		}))
86	}
87	
88	// connectWithHeaderCarrier is a helper for Connect service wrappers that need to set response headers.
89	//
90	// It injects a HeaderCarrier into the context, calls the service method,
91	// and applies any headers from the carrier to the Connect response.
92	//
93	// The generic parameter T is the non-pointer protobuf message type (e.g., v1pb.CreateSessionResponse),
94	// while fn returns *T (the pointer type) as is standard for protobuf messages.
95	//
96	// Usage in Connect wrappers:
97	//
98	//	func (s *ConnectServiceHandler) CreateSession(ctx context.Context, req *connect.Request[v1pb.CreateSessionRequest]) (*connect.Response[v1pb.CreateSessionResponse], error) {
99	//	    return connectWithHeaderCarrier(ctx, func(ctx context.Context) (*v1pb.CreateSessionResponse, error) {
100	//	        return s.APIV1Service.CreateSession(ctx, req.Msg)
101	//	    })
102	//	}
103	func connectWithHeaderCarrier[T any](ctx context.Context, fn func(context.Context) (*T, error)) (*connect.Response[T], error) {
104		// Inject header carrier for Connect protocol
105		ctx = WithHeaderCarrier(ctx)
106	
107		// Call the service method
108		resp, err := fn(ctx)
109		if err != nil {
110			return nil, convertGRPCError(err)
111		}
112	
113		// Create Connect response
114		connectResp := connect.NewResponse(resp)
115	
116		// Apply any headers set via the header carrier
117		if carrier := GetHeaderCarrier(ctx); carrier != nil {
118			for key, value := range carrier.All() {
119				connectResp.Header().Set(key, value)
120			}
121		}
122	
123		return connectResp, nil
124	}
