68	//
69	// This function works for both gRPC and Connect protocols:
70	//   - For gRPC: Uses grpc.SetHeader to set headers in gRPC metadata
71	//   - For Connect: Stores in HeaderCarrier for Connect wrapper to apply later
72	//
73	// The protocol is automatically detected based on whether a HeaderCarrier
74	// exists in the context (injected by Connect wrappers).
75	func SetResponseHeader(ctx context.Context, key, value string) error {
