103	func connectWithHeaderCarrier[T any](ctx context.Context, fn func(context.Context) (*T, error)) (*connect.Response[T], error) {
104		// Inject header carrier for Connect protocol
105		ctx = WithHeaderCarrier(ctx)
106	
107		// Call the service method
108		resp, err := fn(ctx)
109		if err != nil {
110			return nil, convertGRPCError(err)
111		}
112	
113		// Create Connect response
114		connectResp := connect.NewResponse(resp)
115	
116		// Apply any headers set via the header carrier
117		if carrier := GetHeaderCarrier(ctx); carrier != nil {
118			for key, value := range carrier.All() {
119				connectResp.Header().Set(key, value)
120			}
121		}
122	
123		return connectResp, nil
124	}
